  "literacy.tutorial.title": "ਕਲਾਕ੍ਰਿਤੀ ਵਿੱਚ ਜੀ ਆਇਆਂ ਨੂੰ — ਇਹ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ",
  "literacy.tutorial.subtitle": "ਕਾਰੀਗਰਾਂ ਲਈ ਸਰਲ ਪ੍ਰਬੰਧ। ਕੰਪਿਊਟਰ ਗਿਆਨ ਤੋਂ ਬਿਨਾਂ ਪੂਰੇ ਭਾਰਤ ਵਿੱਚ ਵੇਚੋ।",
  "literacy.tutorial.step1Title": "1. ਆਪਣੀ ਮਾਂ-ਬੋਲੀ ਵਿੱਚ ਬੋਲੋ",
  "literacy.tutorial.step1Desc": "ਟਾਈਪ ਕਰਨ ਦੀ ਲੋੜ ਨਹੀਂ। ਸਿਰਫ਼ ਬੋਲ ਕੇ ਸਮਾਨ ਦਾ ਵਰਣਨ ਕਰੋ, ਸਾਡਾ AI ਲਿਖੇਗਾ।",
  "literacy.tutorial.step2Title": "2. ਆਟੋਮੈਟਿਕ AI ਸਟੂਡੀਓ ਫ਼ੋਟੋਆਂ",
  "literacy.tutorial.step2Desc": "ਸਾਧਾਰਨ ਮੋਬਾਈਲ ਨਾਲ ਫ਼ੋਟੋ ਲਵੋ। AI ਪਿਛੋਕੜ ਸਾਫ਼ ਕਰਕੇ ਸੁੰਦਰ ਰੌਸ਼ਨੀ ਦੇਵੇਗਾ।",
  "literacy.tutorial.step3Title": "3. ਸਹੀ ਕੀਮਤ ਨਿਰਧਾਰਨ ਸਲਾਹ",
  "literacy.tutorial.step3Desc": "ਕੱਚਾ ਮਾਲ ਅਤੇ ਦਿਹਾੜੀ ਜੋੜ ਕੇ ਵਾਜਬ ਕੀਮਤ ਤੈਅ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।",
  "literacy.tutorial.step4Title": "4. ਸਿੱਧੇ ਬੈਂਕ ਖਾਤੇ ਵਿੱਚ ਭੁਗਤਾਨ (DBT)",
  "literacy.tutorial.step4Desc": "ਗਾਹਕਾਂ ਦੇ ਪੈਸੇ ਸਿੱਧੇ ਤੁਹਾਡੇ ਬੈਂਕ ਖਾਤੇ ਵਿੱਚ ਆਉਂਦੇ ਹਨ। ਕੋਈ ਕਮਿਸ਼ਨ ਨਹੀਂ।",
