  "privacy.lastUpdated": "ਆਖਰੀ ਅੱਪਡੇਟ ਕੀਤਾ: ਸਤੰਬਰ 2026 • ਭਾਰਤ ਸਰਕਾਰ ਰਾਸ਼ਟਰੀ ਡਿਜੀਟਲ ਬੁਨਿਆਦੀ ਢਾਂਚਾ",
  "privacy.section1.heading": "1. ਵਿਧਾਨਕ ਵਚਨਬੱਧਤਾ ਅਤੇ ਸਕੋਪ",
  "privacy.section2.heading": "2. ਡੇਟਾ ਅਸੀਂ ਇਕੱਠਾ ਕਰਦੇ ਹਾਂ (ਡੇਟਾ ਘੱਟ ਕਰਨ ਦਾ ਸਿਧਾਂਤ)",
  "privacy.section3.heading": "3. ਪ੍ਰੋਸੈਸਿੰਗ ਅਤੇ ਸਿੱਧੀ ਅਦਾਇਗੀ ਦਾ ਉਦੇਸ਼",
  "privacy.section3.intro": "ਇਕੱਤਰ ਕੀਤੇ ਗਏ ਡੇਟਾ ਨੂੰ ਸਿਰਫ਼ ਨਿਮਨਲਿਖਤ ਸਪਸ਼ਟ ਉਦੇਸ਼ਾਂ ਲਈ ਸੰਸਾਧਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ:",
  "privacy.section3.bullet1": "0% ਪਲੇਟਫਾਰਮ ਕਟੌਤੀਆਂ ਦੇ ਨਾਲ ਕਾਰੀਗਰ ਗਿਲਡਾਂ ਨੂੰ ਸਿੱਧੇ DBT ਬੈਂਕ ਭੁਗਤਾਨਾਂ ਦੀ ਸਹੂਲਤ ਦੇਣਾ।",
  "privacy.section3.bullet2": "ਟੈਂਪਰ-ਪਰੂਫ ਕ੍ਰਿਪਟੋਗ੍ਰਾਫਿਕ Ed25519 ਡਿਜ਼ੀਟਲ ਪ੍ਰੋਵੇਨੈਂਸ ਸਰਟੀਫਿਕੇਟਾਂ ਨੂੰ ਟਿਕਾਣਾ।",
  "privacy.section3.bullet4": "SMS ਅਤੇ ਈਮੇਲ ਦੁਆਰਾ ਪੂਰਤੀ ਅਤੇ ਡਿਲੀਵਰੀ ਸਥਿਤੀ ਦੀਆਂ ਸੂਚਨਾਵਾਂ ਨੂੰ ਯਕੀਨੀ ਬਣਾਉਣਾ।",
  "privacy.section4.heading": "4. ਥਰਡ-ਪਾਰਟੀ ਡਾਟਾ ਵੇਚਣ 'ਤੇ ਪੂਰਨ ਪਾਬੰਦੀ",
  "privacy.section5.heading": "5. ਕ੍ਰਿਪਟੋਗ੍ਰਾਫਿਕ ਸੁਰੱਖਿਆ ਅਤੇ ਕੂਕੀ ਨੀਤੀ",
  "privacy.section6.heading": "6. ਡਾਟਾ ਵਿਸ਼ੇ ਦੇ ਅਧਿਕਾਰ ਅਤੇ ਸ਼ਿਕਾਇਤ ਨਿਵਾਰਣ",
